import * as T from 'three';
// Shared bounded effects; every transient owns and releases its geometry/material.
export function makeEffects(parent){
 const root=new T.Group();parent.add(root);const active=[],limit=220;
 const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d'),gr=g.createRadialGradient(32,32,0,32,32,31);gr.addColorStop(0,'#fff');gr.addColorStop(.25,'#ffffffe0');gr.addColorStop(1,'#ffffff00');g.fillStyle=gr;g.fillRect(0,0,64,64);const glow=new T.CanvasTexture(c);
 function add(mesh,life,velocity=null,spin=0,grow=0){while(active.length>=limit)drop(0);root.add(mesh);active.push({mesh,life,total:life,velocity,spin,grow,opacity:mesh.material.opacity});return mesh;}
 function drop(i){const a=active[i];root.remove(a.mesh);a.mesh.geometry?.dispose();a.mesh.material.dispose();active.splice(i,1);}
 function material(color,opacity=1,additive=true){return new T.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,side:T.DoubleSide,blending:additive?T.AdditiveBlending:T.NormalBlending,toneMapped:false});}
 function mote(x,y,z,color,life=.5,size=.4,velocity=new T.Vector3()){const m=new T.Sprite(new T.SpriteMaterial({map:glow,color,transparent:true,opacity:.8,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));m.position.set(x,y,z);m.scale.setScalar(size);return add(m,life,velocity,0,.6);}
 function ring(p,r,color,life=.5){const m=new T.Mesh(new T.RingGeometry(r*.93,r,72),material(color,.8));m.rotation.x=-Math.PI/2;m.position.set(p.x,(p.y||0)+.08,p.z);return add(m,life,null,0,1.1);}
 function slash(p,combo=0,fire=false){const radius=fire?4.5:2.7;for(let layer=0;layer<3;layer++){const pos=[],idx=[],segments=44;for(let i=0;i<=segments;i++){const a=p.facing-1.2+i/segments*2.4;for(const r of [radius-(.3-layer*.08)*Math.sin(Math.PI*i/segments),radius])pos.push(p.x+Math.sin(a)*r,(p.y||0)+.95+Math.sin(a-p.facing)*(combo%2?-.5:.5),p.z+Math.cos(a)*r);if(i){const k=i*2;idx.push(k-2,k-1,k,k-1,k+1,k);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setIndex(idx);const m=new T.Mesh(geo,material(fire?[0xff9b36,0xffd981,0xffffdc][layer]:[0x77e4d4,0xdcfff1,0xffffe2][layer],.75));add(m,.24+layer*.025);}
 for(let i=0;i<(fire?20:7);i++){const a=p.facing+(Math.random()-.5)*2.1,r=radius*(.5+Math.random()*.5);mote(p.x+Math.sin(a)*r,(p.y||0)+.5+Math.random(),p.z+Math.cos(a)*r,fire?0xffbb57:0xe7ffc9,.3+Math.random()*.3,.15+Math.random()*.25,new T.Vector3(Math.sin(a),fire?2:1,Math.cos(a)));}}
 function burst(p){ring(p,7.8,0xffce83,.7);ring(p,5.8,0xfff4bc,.5);for(let j=0;j<8;j++){const a=j/8*Math.PI*2;for(let i=0;i<5;i++){const r=1+i*1.3;mote(p.x+Math.sin(a)*r,(p.y||0)+.3,p.z+Math.cos(a)*r,0xffbf65,.5+i*.08,.7,new T.Vector3(Math.sin(a)*2,2.5+i*.5,Math.cos(a)*2));}}}
 function impact(p,fire=false,steam=false){for(let i=0;i<(steam?15:7);i++)mote(p.x,(p.y||0)+.7,p.z,steam?0xdaf5ff:fire?0xffb866:0xfff7cf,.24+Math.random()*.4,steam?.7:.25,new T.Vector3((Math.random()-.5)*4,1+Math.random()*3,(Math.random()-.5)*4));}
 function dash(p){for(let i=0;i<4;i++){const m=new T.Mesh(new T.PlaneGeometry(.45,1.6),material(0xc8eee2,.3-i*.045));m.position.set(p.x-Math.sin(p.facing)*i*.5,(p.y||0)+.9,p.z-Math.cos(p.facing)*i*.5);m.rotation.y=p.facing;add(m,.2+i*.05);}for(let i=0;i<8;i++)mote(p.x,(p.y||0)+Math.random()*1.5,p.z,0xdcffeb,.3,.17,new T.Vector3(-Math.sin(p.facing)*4,0,-Math.cos(p.facing)*4));}
 return{slash,burst,impact,dash,ring,mote,update(dt){for(let i=active.length-1;i>=0;i--){const a=active[i];a.life-=dt;if(a.life<=0){drop(i);continue;}a.mesh.material.opacity=a.opacity*a.life/a.total;if(a.velocity)a.mesh.position.addScaledVector(a.velocity,dt);if(a.grow)a.mesh.scale.multiplyScalar(1+a.grow*dt);a.mesh.rotation.z+=a.spin*dt;}},clear(){while(active.length)drop(active.length-1);},get count(){return active.length;}};
}
